import type {HandoffScope} from './cashier-handoff';
export function bankBalanceInput(value:string){if(!/^-?\d{1,13}(\.\d{1,2})?$/.test(value))throw Error('Enter a balance with up to two decimal places.');const negative=value.startsWith('-'),[whole,fraction='']=value.replace('-','').split('.');const n=BigInt(whole)*BigInt(100)+BigInt(fraction.padEnd(2,'0'));if(n>BigInt(999999999999999))throw Error('Balance is too large.');return ((negative?-BigInt(1):BigInt(1))*n).toString()}
export function readBankClose(value:unknown,scope:HandoffScope,bank:string,start:string,end:string,opening:string,closing:string){
 if(!value||typeof value!=='object')throw Error('Invalid reconciliation review.');const r=value as Record<string,unknown>;
 if(r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.bank_id!==bank||r.start_date!==start||r.end_date_exclusive!==end||r.opening_minor!==opening||r.closing_minor!==closing||r.close_supported!==false||r.bank_verified!==false)throw Error('Reconciliation review does not match this property and period.');
 const keys=['opening_minor','closing_minor','expected_closing_minor','difference_minor','credits_minor','debits_minor','unposted_minor','ledger_closing_minor','statement_ledger_difference_minor'] as const;for(const k of keys)if(typeof r[k]!=='string'||! /^-?\d+$/.test(r[k] as string))throw Error('Invalid reconciliation amount.');
 const amount=(k:typeof keys[number])=>BigInt(r[k] as string);if(amount('credits_minor')<BigInt(0)||amount('debits_minor')<BigInt(0)||amount('unposted_minor')<BigInt(0)||amount('opening_minor')+amount('credits_minor')-amount('debits_minor')!==amount('expected_closing_minor')||amount('closing_minor')-amount('expected_closing_minor')!==amount('difference_minor')||amount('closing_minor')-amount('ledger_closing_minor')!==amount('statement_ledger_difference_minor'))throw Error('Reconciliation amounts do not balance.');
 const ledger=r.ledger_review as Record<string,unknown>|null;if(!ledger||ledger.tenant_id!==scope.tenant||ledger.property_id!==scope.property||ledger.bank_id!==bank||ledger.start_date!==start||ledger.end_date_exclusive!==end||typeof ledger.shared_with_other_banks!=='boolean'||!Array.isArray(ledger.accounts))throw Error('Invalid bank ledger review.');
 if(ledger.schema_version!==1||ledger.actor_id!==scope.actor||ledger.currency!=='USD'||ledger.basis!=='recorded_general_ledger_journals'||ledger.bank_verified!==false||ledger.close_supported!==false)throw Error('Invalid bank ledger identity.');
 let total=BigInt(0),openingTotal=BigInt(0);const seen=new Set<string>();for(const row of ledger.accounts){if(!row||typeof row!=='object'||typeof row.account_id!=='string'||seen.has(row.account_id)||row.account_kind!=='asset'||typeof row.closing_debit_minor!=='string'||typeof row.closing_credit_minor!=='string'||!/^\d+$/.test(row.closing_debit_minor)||!/^\d+$/.test(row.closing_credit_minor))throw Error('Invalid bank account balance.');if(typeof row.opening_debit_minor!=='string'||typeof row.opening_credit_minor!=='string'||!/^\d+$/.test(row.opening_debit_minor)||!/^\d+$/.test(row.opening_credit_minor))throw Error('Invalid bank opening balance.');openingTotal+=BigInt(row.opening_debit_minor)-BigInt(row.opening_credit_minor);seen.add(row.account_id);total+=BigInt(row.closing_debit_minor)-BigInt(row.closing_credit_minor);}if(total!==amount('ledger_closing_minor'))throw Error('Bank ledger total does not match its accounts.');
 return {scope,bank,start,end,opening,closing,ledgerOpening:openingTotal.toString(),openingDifference:(BigInt(opening)-openingTotal).toString(),statementDifference:r.difference_minor as string,ledgerBalance:r.ledger_closing_minor as string,ledgerDifference:r.statement_ledger_difference_minor as string,unposted:r.unposted_minor as string,configured:ledger.accounts.length>0,shared:ledger.shared_with_other_banks};
}
export function bankCloseMoney(value:string){const n=BigInt(value),abs=n<BigInt(0)?-n:n;return (n<BigInt(0)?'-':'')+'$'+(abs/BigInt(100)).toLocaleString('en-US')+'.'+(abs%BigInt(100)).toString().padStart(2,'0')}

export function bankCloseRows(r:ReturnType<typeof readBankClose>):string[][]{return [['iRatePilot PMS','Bank statement closing review'],['Status','Review only; bank close not finalized'],['Currency','USD'],['Tenant reference',r.scope.tenant],['Property reference',r.scope.property],['Bank reference',r.bank],['Statement start',r.start],['Statement end (exclusive)',r.end],['Opening statement balance',bankCloseMoney(r.opening)],['Closing statement balance',bankCloseMoney(r.closing)],['Recorded ledger opening',bankCloseMoney(r.ledgerOpening)],['Statement opening minus ledger',bankCloseMoney(r.openingDifference)],['Statement arithmetic difference',bankCloseMoney(r.statementDifference)],['Recorded bank ledger balance',bankCloseMoney(r.ledgerBalance)],['Statement minus ledger',bankCloseMoney(r.ledgerDifference)],['Statement amount not posted',bankCloseMoney(r.unposted)],['Bank ledger configured',r.configured?'Yes':'No'],['Ledger shared with another bank',r.shared?'Yes':'No'],['Bank independently verified','No']]}
